      [.05, .025].forEach((d, k) => { const w0 = wx102(Object.assign({}, o, { t: o.t - d })); if (Math.abs(w0 - wx) > 1.5) { ctx.save(); ctx.globalAlpha *= .12 * (k + 1) * al; ctx.fillStyle = '#c8beb4'; ctx.beginPath(); ctx.arc(w0, top - r, r, 0, 7); ctx.fill(); ctx.restore(); } });
