        if (falling) dy = -28 * (1 - Math.pow((o.t + .4) / .4, 2)); else if (drop && k === kc && o.t >= 0 && o.t < .3) dy = -Math.abs(Math.sin(Math.PI * o.t / .3)) * 3;
