      for (let k = 0; k < G.N; k++) { const fr = G.fr(k), d = drop124(k, kn, o), x = G.sx(k), r = R(k), n = Nt(k), dir = k % 2 ? -1 : 1, rot = dir * th * Math.PI * 2 / n + (mesh && k % 2 ? Math.PI / n : 0);
        if (fr <= 0 && !d.fly) { ctx.strokeStyle = 'rgba(200,180,140,.18)'; ctx.lineWidth = 1; ctx.beginPath(); ctx.arc(x, y, r * .85, 0, 7); ctx.stroke(); continue; }
        gear124(x, y + d.dy, r, n, d.fly ? 0 : rot, k % 2 ? '#9aa4b0' : '#c8a050', d.fly ? .9 : .45 + .55 * Math.max(fr, 0)); }
