        for (let q = 0; q < 9; q++) spawn({ x: tip, y: y - 2, vx: (Math.random() - .4) * 80, vy: -40 - Math.random() * 70, g: 320, life: .8, size: 1.4, shape: 'sq', vr: 9, col: q % 2 ? '#5a4030' : '#7a5a3e' });
