          for (let j = 0; j < 6; j++) { const x = I.x0 + ((t * (18 + j * 5) + j * 41) % (ft - I.x0 + 8)); ctx.fillStyle = 'rgba(230,255,200,.5)'; ctx.beginPath(); ctx.arc(x, y + Math.sin(t * 5 + j) * 1.5, 1.2 + (j % 2), 0, 7); ctx.fill(); }
