    ctx.strokeStyle = '#c8a050'; ctx.lineWidth = 1.4; ctx.beginPath(); ctx.moveTo(P0[0] + nx * (r + .8), P0[1] + ny * (r + .8)); ctx.lineTo(P1[0] + nx * (r + .8), P1[1] + ny * (r + .8)); ctx.stroke(); ctx.fillStyle = '#7a5a28'; ctx.fillRect(P0[0] + 2.5, P0[1] - 3, 2, 6);
