    if (P.flutes) { ctx.strokeStyle = P.flutes; ctx.lineWidth = 1; for (let j = 0; j < 6; j++) { const an = rot + (j + .5) * Math.PI / 3; ctx.beginPath(); ctx.moveTo(dx + Math.cos(an) * 5, y + Math.sin(an) * 5); ctx.lineTo(dx + Math.cos(an) * 10, y + Math.sin(an) * 10); ctx.stroke(); } }
    for (let j = 0; j < 6; j++) { const an = rot + j * Math.PI / 3, x = dx + Math.cos(an) * 6.2, yy = y + Math.sin(an) * 6.2; ctx.fillStyle = P.hole; ctx.beginPath(); ctx.arc(x, yy, 3.3, 0, 7); ctx.fill(); if (P.ring) { ctx.strokeStyle = P.ring; ctx.lineWidth = .9; ctx.stroke(); }
      if (j < n && !(j === 0 && a >= .5 && a < .62)) gear130(x, yy, 2.4, an, j % 2 ? P.cogs[1] : P.cogs[0], 6); else if (P.emptyGlow) glow126(x, yy, 3, P.emptyGlow); }
