      once('ckdx', () => { glow167(xp, y - 4, 70, .6); spawn({ x: xp, y: y - 4, size: 6, shape: 'ring', grow: 70, life: .6, col: '#fff' }); puff167(xp, y - 8, 16, 'rgba(235,235,235,.7)', 70, 60); });
