  const gg = ctx.createLinearGradient(-4, 0, 0, 0); gg.addColorStop(0, '#f0c870'); gg.addColorStop(1, '#8a6224'); ctx.fillStyle = gg; ctx.beginPath(); ctx.roundRect(-4, -12, 4, 24, 1.5); ctx.fill(); ctx.strokeStyle = '#3a2810'; ctx.stroke();
